INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e7d6d524-f748-4e25-ab8e-a508cb5ae805', 'Incremento de Renta', '4', '5', 'INCREMENTOS A LA RENTA Y CUOTA DE MANTENIMIENTO', E'- For the first five years of the contract, the rent will not change due to inflation or any other reason.\n- Rent increases are scheduled as follows:\n  - 12% increase at the start of the 6th year\n  - 12% increase at the start of the 11th year\n  - 15% increase at the start of the 16th year\n  - 15% increase at the start of the 21st year\n  - 15% increase at the start of the 26th year, if renewal options are exercised.\n- If the National Consumer Price Index (INPC) increases by more than 5% at the end of any calendar year, rent can increase by the amount over 5%, capped at 7% per fiscal year. This does not affect the scheduled increases every five years.\n  - Example: If INPC is 6.5%, rent can increase by 1.5% the next fiscal year (6.5% - 5% = 1.5%).\n  - If INPC is 7.2%, rent can increase by 2% the next fiscal year, as it is capped (7.2% - 5% = 2.2%, but capped at 2%).\n- These exceptional increases can be applied starting December 31, 2020, if needed.\n- The maintenance fee will increase annually based on the INPC but will not exceed a 5% increase in any year of the contract term.', E'Durante los primeros cinco (5) años del presente Contrato, la Renta no sufrirá variaciones ni incrementos por concepto de inflación ni actualización según el Índice Nacional de Precios al Consumidor o cualquier otro concepto o motivo.\n\nLas Partes acuerdan que la Renta será incrementada en los siguientes términos: en un doce por ciento (12%) a partir del primer mes del inicio del sexto año, en un doce por ciento (12%) a partir del primer mes del inicio del undécimo año, en un quince por ciento (15%) a partir del primer mes del inicio del dieciseisavo año, en un quince por ciento (15%) a partir del primer mes del inicio del vigésimo primer año; en un quince por ciento (15%) a partir del primer mes del inicio del vigesimosexto año; ello, cuando se ejerzan las opciones de prórroga.\n\nSi el Indice Nacional de Precios al Consumidor ("INPC") incrementa al término de cualquier año calendario en un porcentaje mayor al cinco por ciento (5%) respecto del año anterior inmediato, la Renta podrá incrementar en la cantidad neta por encima del cinco porciento (5%) y topada al siete por ciento (7%) de cada año fiscal. Ello, sin modificar los incrementos pactados cada cinco (5) años en los términos del presente Contrato.\n\nPor ejemplo: En el año uno (1) el INPC es del seis punto cinco por ciento (6.5%), el siguiente año fiscal la Renta podrá incrementarse por uno punto cinco por ciento (1.5%); a manera ejemplificativa 6.5%-5% = 1.5%. En el año dos, el INPC incrementa a slete punto dos por ciento (7.2%), siguiente año fiscal la Renta podrá incrementarse por dos por ciento (2%); a manera ejemplificativa, si bien, 7.2% -5% = 2.2%, el incrementó será de dos por ciento (2%) por estar topada. Dichos aumentos excepcionales podrán ejercitarse a partir del treinta y uno (31) de diciembre dos mil veinte (2020), cuando sea requerido.\n\nLa Cuota de Mantenimiento se incrementará anualmente en base al INCP, sin embargo en ningún momento podrá incrementarse por mas del 5% en cualquier año del plazo del presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('e7d6d524-f748-4e25-ab8e-a508cb5ae805', 'Common Area Maintenance Charges', '4', '4', 'CUOTA DE MANTENIMIENTO', E'- The Tenant must pay the Landlord a monthly maintenance fee of $35.00 per square meter.\n- This amounts to $105,427.35 in total, plus Value Added Tax (VAT).\n- The payment should be deposited into a bank account in Mexico specified by the Tenant.', 'El Arrendatario se obliga a pagar al Arrendador por concepto de cuota de mantenimiento la cantidad mensual de $35.00 (Treinta y Cinco Pesos 00/100 Moneda Nacional) por metro cuadrado, equivalentes a $105,427.35 (Ciento Cinco Mil Cuatrocientos Veintisiete Pesos 35/100 Moneda Nacional) más el Impuesto al Valor Agregado, la cual deberá ser depositada en la cuenta bancaria ubicada en México que señale el Arrendatario (la "Cuota de Mantenimiento").');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('8b2645bb-c7bb-466d-b62e-df19639ee5ce', 'Plaza San Marcos', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'S/N Avenida Chalma, Equina Autopista México-Querétaro', 'G-01', 'Jardines De La Hacienda Sur, Cuautitlán Izcalli', 'Estado de México', '54720', 'MX', 'S/N Avenida Chalma, Equina Autopista México-Querétaro, G-01, Jardines De La Hacienda Sur, Cuautitlán Izcalli, Estado de México 54720', 19.6708684058, -99.2081750096, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'San Marcos Power Center', 2030.76, 2030.76, NULL, '{"map_lease_expiration_date":"2032-06-02","map_marker_color":"#A879D2","coordinate":"point|19.6708684058|-99.2081750096|accurate","city_state":"Jardines De La Hacienda Sur, Cuautitlán Izcalli, Estado de México","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Avenida Santa Fe 481, Piso 7, Cruz Manca, Ciudad de México 05349","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2037-06-02","lease_expiration_date":"2032-06-02","lease_renewal_notice":"120 Days Prior","lease_length_in_months_remaining":68,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57