INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', '8b2645bb-c7bb-466d-b62e-df19639ee5ce', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Plaza San Marcos Lease: Promotora Izcalli 2003, S.A.P.I. De C.V. (06/03/2022 - 06/02/2032)', 'Not sure', false, 'activo', 'Lease', NULL, '2022-07-01', '2022-01-03', '2032-06-02', '2037-06-02', false, 1, NULL, 1, NULL, NULL, '2032-02-03', 'Send Notice to Renew', 119, 'Promotora Izcalli 2003, S.A.P.I. De C.V.', NULL, NULL, 'Avenida Santa Fe 481', 'Piso 7', 'Cruz Manca', 'Ciudad de México', '05349', 'MX', NULL, NULL, NULL, 150, 'percent', NULL, NULL, 1034640, 'La Arrendataria deberá entregar a más tardar a la firma del presente contrato, la cantidad de $1''034,640.00 M.N. + I.V.A., equivalente a 3 meses de renta , las cuales setán efectivas para su cobro en las mensualidades 4, 8  y 12.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', 'Domicilio del Contrato', E'Avenida Chalma S/N, Esquina Autopista Mexico-Querétaro, Colonia Jardines de la Hacienda Sur, Municipio de Cuautitlán Izcalli, Estado de México, CP54720.\nLocalidad comercial que se identifica con el No. G-01', 'America Gonzalez', NULL);
