INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', 'Fecha de Apertura', '7 de abril de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', 'Late Fees', '6', '3.4', 'RENTA E INCREMENTOS', E'- If the tenant does not pay the rent and VAT on time as agreed in the contract, they must pay the landlord interest.\n- The interest rate is 10% per month plus the applicable VAT.\n- Interest is calculated from the date the payment is late until the date the full amount is paid.', 'Para el caso de que el "Arrendatario" no cubra puntualmente la Renta y el I.V.A. respectivo en la forma estipulada en el presente contrato, se obliga a pagarle al "Arrendador los Intereses que habrán de ser calculados a una tasa del 10% (diez por ciento) mensual más el I.V.A. correspondiente, a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente haya pagado el importe de tales conceptos.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', 'Incremento de Renta', '6', '3.8', 'RENTA E INCREMENTOS', E'- La renta mensual aumentará cada 12 meses desde la fecha de inicio del pago de renta.\n- El primer aumento será después de 12 meses, basado en la inflación de ese período.\n- El aumento no puede ser mayor al 6%.\n- Este proceso se repetirá cada 12 meses.\n- Para calcular la inflación, se comparará el Índice Nacional de Precios al Consumidor del mes anterior al inicio del período de 12 meses con el índice del último mes de ese período.\n- El porcentaje de aumento se aplicará a la renta actual, y el resultado será la nueva renta mensual para los próximos 12 meses, más el IVA correspondiente.', 'Las partes convienen en que el monto de la Renta mensual convenida en el inciso 3.1 de esta cláusula será incrementado cada doce meses a partir de la Fecha de Inicio de Pago de Renta. El primer incremento se hará una vez transcurridos doce meses contados a partir de la Fecha de Inicio de Pago de Renta, de conformidad con la Inflación del mismo período, no pudiendo ser en ningún caso mayor a un 6% (seis por ciento). El mismo procedimiento se repetirá cada doce meses a partir de la Fecha de Inicio de Pago de Renta. Para la determinación de la Inflación del periodo de que se trate, se comparará el Índice Nacional de Precios al Consumidor del mes inmediato anterior al del inicio del período de doce meses, con el Índice del último mes de dicho período. El incremento porcentual resultante de estos doce meses se aplicará al importe de la Renta vigente; el resultado se sumará a la última Renta y la cantidad que así resulte será el importe de la Renta mensual para los siguientes doce meses, más el I.V.A. correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('444d1ceb-bd8b-4760-b8ab-aa587ab57556', 'Common Area Maintenance Charges', '10', '13 a)', 'CUOTAS DE MANTENIMIENTO Y OTROS CONCEPTOS', E'- The tenant must pay a monthly amount equal to 15% of the rent.\n- This payment is for the purpose specified in this section.\n- Payment should be made via deposit or transfer to the bank account listed for maintenance payment.\n- A different percentage may apply if specified in the Shopping Center''s Operation and Functioning Regulations.', 'Salvo que el Reglamento de Operación y Funcionamiento del Centro Comercial prevea un porcentaje distinto, el "Arrendatario" deberá pagar por el concepto previsto en el presente inciso, una cantidad mensual equivalente al 15 % (Quince por ciento) de la Renta mediante depósito o transferencia de fondos en la Cuenta Bancaría para realizar el Pago del Mantenimiento descrita en LA CARÁTULA.');
