udad Satélite, Naucalpan De Juárez, Estado de México 53100","map_addr_1":"2251 Circuito Centro Comercial","map_addr_2":"S02","map_city_state_zip":"Ciudad Satélite, Naucalpan De Juárez, Estado de México 53100","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2025-10-06 14:21:02","active_lease_count_over_time":51322,"location_count_over_time":57973,"remaining_rent_liability_over_time":51322}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', '0843f7de-9a04-4f19-9093-8938a52a60af', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Plaza Satélite Lease: Bancomer, S.A, Fideicomiso F7278-5 (02/15/2022 - 06/14/2027)', NULL, false, 'activo', 'Lease', NULL, '2022-06-01', '2022-02-15', '2027-06-14', '2037-06-14', false, 2, NULL, 2, NULL, NULL, '2027-04-15', 'Send Notice to Renew', 63, 'Bancomer, S.A, Fideicomiso F7278-5', NULL, NULL, '2251 Circuito Centro Comercial', NULL, 'Naucalpan De Juárez', 'MX-MEX', '53100', 'MX', NULL, NULL, NULL, 120, 'percent', NULL, 720280.8, NULL, NULL, NULL, true, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"is_next_percent_rent_payment":"No"}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Domicilio del Contrato', E'No. 2251, del Fraccionamiento de Ciudad Satélite, Municipio de Naucalpan de Juárez, Estado de México\nLocal número S02', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Fecha de Firma del Contrato', '14 de diciembre de 2021', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Fecha de Apertura', '6 de junio de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Late Fees', '11', '4', 'INTERESES MORATORIOS', E'- Si el inquilino se retrasa en el pago del alquiler, debe pagar intereses por cada día de retraso.\n- Los intereses se calculan multiplicando por 2 la Tasa de Interés Interbancaria de Equilibrio (TIIE) a 28 días, publicada por el Banco de México.\n- Si la TIIE deja de existir, se usará una tasa que la reemplace o una equivalente definida por el arrendador.', E'En caso de retraso en el pago de la Renta, la Arrendataria se obliga a pagar a la Arrendadora por concepto de intereses moratorios, por cada día que la Arrendataria permanezca en mora, el equivalente a la cantidad que resulte de multiplicar por 2 (dos) la Tasa de Interés Interbancaria de Equilibrio a plazo de 28 días publicada por el Banco de México en el Diario Oficial de la Federación ("TIIE”) el Día Hábil inmediato anterior al de la fecha en que la Arrendataria incurra en mora de la obligación de pago correspondiente conforme al presente Contrato.\n\nEn caso de que por cualquier circunstancia dejare de existir la TIIE, ésta será sustituida por aquella tasa que reemplace a la TIIE, o cualquier otra equivalente a dicha tasa definida por la Arrendadora.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Incremento de Renta', '1', '1', 'INCREMENTO DE LA RENTA', E'- The fixed monthly rent and additional rent will increase annually on June 1st.\n- The increase is based on a specific adjustment factor and current market values for the property.\n- The adjustment factor is calculated using the National Consumer Price Index (INPC).\n- The increase cannot exceed 6% of the current rent value.', E'La Renta Mensual Fija y Renta Adicional pactadas en esta Cláusula serán incrementadas en forma Anual el primer día del mes de junio de cada año, aplicando a dichos conceptos del último mes anterior al ajuste, el factor a que se refiere el párrafo siguiente, así como tomando en consideración los Valores de Mercado aplicables al inmueble en materia de arrendamiento que en su momento rijan y que se encuentren vigentes.\n\nEl factor de ajuste para efectos del párrafo anterior se calculará dividiendo el último INPC publicado en fecha anterior al del mes previo al incremento de la Renta Mensual Fija y Renta Adicional entre el último publicado al mes de inicio del arrendamiento o al mes del último ajuste, según corresponda. En la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 6% del valor de la contraprestación vigente que opere en dicho período.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Common Area Maintenance Charges', '8', '2', 'CONTRAPRESTACIÓN', E'- La arrendataria debe pagar $72,028.08 MXN más IVA cada mes, dentro de los primeros 5 días naturales.\n- Este pago se llama "Renta Adicional" y cubre gastos de conservación y funcionalidad del inmueble.\n- El pago debe hacerse en una sola exhibición junto con el IVA u otros impuestos aplicables.\n- La Renta Adicional comienza a pagarse después del Periodo de Gracia o desde la Fecha de Apertura, lo que ocurra primero.\n- Los servicios de conservación y funcionalidad serán proporcionados por empleados o proveedores contratados por la arrendadora.\n- La arrendataria no puede contratar estos servicios por su cuenta sin autorización escrita de la arrendadora.', E'Asimismo, la Arrendataria se obliga a pagar mensualmente, la cantidad de $72,028.08 M.N. (setenta y dos mil veintiocho pesos 08/100 moneda nacional), más el IVA que le corresponda dentro de los primeros 05 (cinco) días naturales de cada mes correspondiente (en adelante la "Renta Adicional").\nEl importe de la Renta Adicional deberá ser pagada conjuntamente en una sola exhibición con el IVA correspondiente o cualquier otro impuesto o contribución que le sustituya, a partir del día siguiente al que venza el Periodo de Gracia, o a partir de lạ Fecha de Apertura, lo que suceda primero. \n\nEl concepto Renta Adicional será un ingreso por arrendamiento destinado a cubrir todos los gastos por la conservación y funcionalidad del inmueble.\nLas Partes acuerdan que los servicios de conservación y funcionalidad siempre serán prestados a través de los empleados o proveedores que para ello contrate la Arrendadora, por lo que la Arrendataria, no podrá contratar directamente dichos servicios sin la autorización previa y por escrito de la Arrendadora.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('4e557d3b-1330-4754-99ef-1460ff82a5ad', 'Percentage Rent', '9', '2', 'CONTRAPRESTACIÓN', E'- If 9% of the Net Sales for the month is more than the Fixed Monthly Rent, the tenant must pay the landlord the difference plus applicable VAT as Variable Rent.\n- If 9% of the Net Sales is less than the Fixed Monthly Rent, the tenant does not pay any additional amount as Variable Rent for that month.', E'Adicionalmente, si el 09% (nueve por ciento) de las VENTAS NETAS (conforme la definición señalada más adelante) durante el mes que corresponda es superior a la Renta Mensual Fija, la Arrendataria deberá pagar a la Arrendadora, además de lo que hubiese pagado por concepto de Renta Mensual Fija, el total de dicha diferencia más el Impuesto al Valor Agregado correspondiente, misma que se considerará como Renta Variable.\n\nSi el 09% (nueve por ciento) de dichas Ventas Netas durante el mes que corresponda es inferior a la Renta Mensual Fija, la Arrendataria no pagará en ese mes diferencia alguna a "LA ARRENDADORA” por concepto de Renta Variable.');
